"""Migrated Meridian CRM 4.2 order validation rules."""

from decimal import Decimal, InvalidOperation
from typing import Any


def _value(record: dict | None, column: str) -> Any:
    """Return a field value, treating absent fields and None as empty strings."""
    if record is None:
        return ""
    value = record.get(column, "")
    return "" if value is None else value


def _number(value: Any) -> Decimal:
    """Coerce a value for legacy numeric comparisons."""
    if value is None or value == "":
        return Decimal(0)
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal(0)


def _lookup(
    tables: dict | None,
    table_name: str,
    key_column: str,
    key_value: Any,
    output_column: str,
) -> Any:
    """Implement the legacy LOOKUP function, including soft-delete filtering."""
    if tables is None:
        return ""

    rows = tables.get(table_name, [])
    for row in rows:
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get(key_column, "") == key_value:
            value = row.get(output_column, "")
            return "" if value is None else value

    return ""


def _error(code: str, message: str) -> dict:
    return {
        "code": code,
        "message": message,
        "severity": "BLOCK",
    }


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    """Run applicable migrated order rules and return all failures."""
    errors: list[dict] = []

    if table == "ORD_HEADER":
        # ORD-001
        if event in ("INSERT", "UPDATE"):
            discount = _number(_value(record, "DISC_PCT"))
            if not (discount >= 0 and discount <= 100):
                errors.append(_error("E5001", "Discount out of range"))

        # ORD-002
        if event == "UPDATE":
            discount = _number(_value(record, "DISC_PCT"))
            owner_role = _lookup(
                tables,
                "USR_MASTER",
                "USR_ID",
                _value(record, "OWNER_UID"),
                "ROLE_ID",
            )
            passes = not (
                discount > 20
                and owner_role != "MGR"
                and owner_role != "ADMIN"
            )
            if not passes:
                errors.append(
                    _error(
                        "E5002",
                        "Discount over 20 percent requires manager role",
                    )
                )

        # ORD-003
        if event == "UPDATE":
            old_status = _value(old, "STAT_CD")
            new_status = _value(record, "STAT_CD")
            passes = not (
                old_status == "I"
                and new_status != "I"
                and new_status != "X"
            )
            if not passes:
                errors.append(
                    _error("E5003", "Invoiced order can only be cancelled")
                )

    elif table == "ORD_LINE":
        # ORD-004
        if event in ("INSERT", "UPDATE"):
            quantity = _number(_value(record, "QTY"))
            if not quantity > 0:
                errors.append(_error("E5004", "Quantity must be positive"))

        # ORD-005
        if event == "INSERT":
            active_flag = _lookup(
                tables,
                "PROD_MASTER",
                "PROD_ID",
                _value(record, "PROD_ID"),
                "ACTIVE_FLG",
            )
            if active_flag != "Y":
                errors.append(_error("E5005", "Product not active"))

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
